// Process-isolated lifecycle benchmark for T2 full-system modules.
//
// Each cold sample starts a fresh Node/V8 process, runs the same deterministic
// six-entry indirect-control workload, and retains raw execution chunks plus
// generated bytes. Separate fresh workers then compile, instantiate, and
// publish those exact frozen bytes without guest translation or execution.
// This prevents a warmed V8 module/code cache or one harness instance's Wasm
// tiering history from leaking into headline frontend numbers.

import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { spawnSync } from "node:child_process";
import { summary } from "./statistics.mjs";

const here = dirname(fileURLToPath(import.meta.url));
const root = join(here, "..");
const self = fileURLToPath(import.meta.url);

const R = (op, f3, f7, rd, rs1, rs2) =>
  op | (rd << 7) | (f3 << 12) | (rs1 << 15) | (rs2 << 20) | (f7 << 25);
const I = (op, f3, rd, rs1, imm) =>
  op | (rd << 7) | (f3 << 12) | (rs1 << 15) | ((imm & 0xfff) << 20);
const S = (f3, rs1, rs2, imm) => {
  const value = imm & 0xfff;
  return 0x23 | ((value & 0x1f) << 7) | (f3 << 12) | (rs1 << 15) |
    (rs2 << 20) | ((value >> 5) << 25);
};
const U = (op, rd, imm20) => op | (rd << 7) | ((imm20 & 0xfffff) << 12);
const B = (f3, rs1, rs2, off) => {
  const value = off & 0x1fff;
  return 0x63 | (f3 << 12) | (rs1 << 15) | (rs2 << 20) |
    (((value >> 11) & 1) << 7) | (((value >> 1) & 0xf) << 8) |
    (((value >> 5) & 0x3f) << 25) | (((value >> 12) & 1) << 31);
};

function program() {
  const code = [
    U(0x37, 31, 0x20),
    I(0x13, 0, 1, 0, 0),
    U(0x17, 10, 0),
    I(0x13, 0, 10, 10, 0x18),
    I(0x67, 0, 0, 10, 0),
    I(0x13, 0, 0, 0, 0),
    I(0x13, 0, 0, 0, 0),
    I(0x13, 0, 0, 0, 0),
  ];
  for (let increment = 1; increment <= 5; increment++) {
    code.push(
      I(0x13, 0, 1, 1, increment),
      U(0x17, 10, 0),
      I(0x13, 0, 10, 10, 0x0c),
      I(0x67, 0, 0, 10, 0),
    );
  }
  code.push(
    I(0x13, 0, 1, 1, 6),
    I(0x13, 0, 31, 31, -1),
    B(0, 31, 0, 16),
    U(0x17, 10, 0),
    I(0x13, 0, 10, 10, -0x5c),
    I(0x67, 0, 0, 10, 0),
    U(0x37, 24, 0x40008),
    I(0x13, 0, 25, 0, 1),
    S(3, 24, 25, 0),
    0x0000_006f,
  );
  const bytes = new Uint8Array(code.length * 4);
  const view = new DataView(bytes.buffer);
  code.forEach((word, index) => view.setUint32(index * 4, word >>> 0, true));
  return bytes;
}

const tick = () => new Promise((resolve) => setImmediate(resolve));

async function workloadWorker(mode) {
  const { RV64Debug: RV64 } = await import(join(root, "web/rv64.js"));
  const wasm = readFileSync(
    join(root, "target/wasm32-unknown-unknown/release/rv64_wasm.wasm"),
  );
  const initStart = performance.now();
  const vm = await RV64.create(wasm);
  const initMs = performance.now() - initStart;
  vm.onWrite = () => {};
  vm.ex.jit_set_enabled(1);
  vm.ex.jit_set_ic_trigger(64);
  if (mode === "batch") vm.ex.jit_set_batch(1);
  if (mode === "region") {
    vm.ex.sys_set_superblock(1);
    vm.ex.jit_set_sb_spacing(0);
  }

  const modules = [];
  vm.onJitModule = (bytes, metadata) => {
    const stableMetadata = Object.fromEntries(
      Object.entries(metadata).map(([key, value]) => [
        key,
        typeof value === "bigint" ? value.toString() : value,
      ]),
    );
    modules.push({
      bytes: Buffer.from(bytes).toString("base64"),
      hash: createHash("sha256").update(bytes).digest("hex"),
      size: bytes.length,
      metadata: stableMetadata,
    });
  };
  vm.bootLinux({ bios: program(), ramMB: 32 });

  const chunks = [];
  let poweredOff = 0;
  while (!poweredOff && chunks.length < 100) {
    const beforeInsns = vm.ex.sys_insn_count();
    const beforeJit = vm.ex.jit_stat(0);
    const beforeDispatches = vm.ex.jit_stat(1);
    const beforeModules = vm.jitRegCount ?? 0;
    const start = performance.now();
    poweredOff = vm.runSystem(100_000n);
    const runMs = performance.now() - start;
    await tick();
    const insns = vm.ex.sys_insn_count() - beforeInsns;
    chunks.push({
      runMs,
      insns: insns.toString(),
      minsnPerSec: runMs > 0 ? Number(insns) / runMs / 1000 : 0,
      jitInsns: (vm.ex.jit_stat(0) - beforeJit).toString(),
      dispatches: (vm.ex.jit_stat(1) - beforeDispatches).toString(),
      newModules: (vm.jitRegCount ?? 0) - beforeModules,
    });
  }
  // Let a final async region publication settle before capturing lifecycle.
  await tick();
  process.stdout.write(JSON.stringify({
    mode,
    engine: { node: process.version, v8: process.versions.v8 },
    initMs,
    poweredOff,
    checksum: vm.ex.sys_reg(1).toString(),
    chunks,
    lifecycle: vm.jitLifecycleStats(),
    counters: {
      jitInsns: vm.ex.jit_stat(0).toString(),
      dispatches: vm.ex.jit_stat(1).toString(),
      batches: vm.ex.jit_stat(43).toString(),
      batchMembers: vm.ex.jit_stat(44).toString(),
      regionIssued: vm.ex.jit_stat(12).toString(),
      regionLanded: vm.ex.jit_stat(13).toString(),
      icExtensions: vm.ex.jit_stat(45).toString(),
    },
    moduleHashes: modules.map((module) => module.hash),
    modules,
  }));
}

function replayWorker() {
  const input = JSON.parse(readFileSync(0, "utf8"));
  const memory = new WebAssembly.Memory({ initial: 1 });
  const modules = input.map((item) => Buffer.from(item.bytes, "base64"));
  const compileStart = performance.now();
  const compiled = modules.map((bytes) => new WebAssembly.Module(bytes));
  const compileMs = performance.now() - compileStart;
  const instantiateStart = performance.now();
  const instances = compiled.map((module) => new WebAssembly.Instance(module, {
    env: {
      memory,
      fp_exec: () => 0n,
      user_reservation: () => 0,
      system_reservation: () => 0,
      tlb_fill: () => -1n,
      system_bulk_copy: () => 0n,
    },
  }));
  const instantiateMs = performance.now() - instantiateStart;
  const functions = instances.flatMap((instance) =>
    Object.values(instance.exports).filter((value) => typeof value === "function"));
  const table = new WebAssembly.Table({ initial: functions.length, element: "anyfunc" });
  const publishStart = performance.now();
  functions.forEach((fn, index) => table.set(index, fn));
  const publishMs = performance.now() - publishStart;
  process.stdout.write(JSON.stringify({ compileMs, instantiateMs, publishMs }));
}

if (process.argv.includes("--worker-run")) {
  const mode = process.argv.find((arg) => arg.startsWith("--mode="))?.split("=")[1] ?? "batch";
  await workloadWorker(mode);
  process.exit(0);
}
if (process.argv.includes("--worker-replay")) {
  replayWorker();
  process.exit(0);
}

const mode = process.argv.find((arg) => arg.startsWith("--mode="))?.split("=")[1] ?? "batch";
if (!new Set(["batch", "region", "ic"]).has(mode)) {
  throw new Error("--mode must be batch, region, or ic");
}
const sampleArg = process.argv.find((arg) => arg.startsWith("--samples="));
const samples = sampleArg ? Number(sampleArg.split("=")[1]) : 3;
if (!Number.isInteger(samples) || samples < 1 || samples > 30) {
  throw new Error("--samples must be an integer from 1 through 30");
}

const runs = [];
for (let index = 0; index < samples; index++) {
  const child = spawnSync(process.execPath, [self, "--worker-run", `--mode=${mode}`], {
    encoding: "utf8",
    maxBuffer: 64 << 20,
  });
  if (child.status !== 0) throw new Error(child.stderr || child.stdout);
  runs.push(JSON.parse(child.stdout));
}
if (runs.some((run) => !run.poweredOff || run.checksum !== "2752512")) {
  throw new Error("T2 lifecycle workload did not complete with the expected checksum");
}

const moduleHashes = runs[0].moduleHashes;
const deterministic = runs.every((run) =>
  JSON.stringify(run.moduleHashes) === JSON.stringify(moduleHashes));
const frozenInput = JSON.stringify(runs[0].modules);
const replays = [];
for (let index = 0; index < samples; index++) {
  const child = spawnSync(process.execPath, [self, "--worker-replay"], {
    input: frozenInput,
    encoding: "utf8",
    maxBuffer: 64 << 20,
  });
  if (child.status !== 0) throw new Error(child.stderr || child.stdout);
  replays.push(JSON.parse(child.stdout));
}

const report = {
  schema: 1,
  mode,
  isolation: "fresh-node-process-per-sample",
  samples,
  engine: runs[0].engine,
  deterministicModuleOrder: deterministic,
  moduleCount: moduleHashes.length,
  moduleHashes,
  moduleKinds: runs[0].modules.map((module) => module.metadata.kind),
  moduleSizes: runs[0].modules.map((module) => module.size),
  cold: {
    totalRunMs: summary(runs.map((run) =>
      run.chunks.reduce((total, chunk) => total + chunk.runMs, 0))),
    translateMs: summary(runs.map((run) => run.lifecycle.systemTranslateMs)),
    copyMs: summary(runs.map((run) => run.lifecycle.copyMs)),
    compileMs: summary(runs.map((run) => run.lifecycle.compileMs)),
    instantiateMs: summary(runs.map((run) => run.lifecycle.instantiateMs)),
    publishMs: summary(runs.map((run) => run.lifecycle.publishMs)),
    rawChunksByProcess: runs.map((run) => run.chunks),
    countersByProcess: runs.map((run) => run.counters),
  },
  frozenFrontend: {
    compileMs: summary(replays.map((replay) => replay.compileMs)),
    instantiateMs: summary(replays.map((replay) => replay.instantiateMs)),
    publishMs: summary(replays.map((replay) => replay.publishMs)),
  },
};

if (process.argv.includes("--json")) {
  console.log(JSON.stringify(report, null, 2));
} else {
  const f = (value) => value.toFixed(3);
  console.log(`engine: Node ${report.engine.node}, V8 ${report.engine.v8}`);
  console.log(
    `T2 mode: ${mode}; ${samples} fresh processes; modules: ${report.moduleCount}; ` +
      `deterministic: ${deterministic}`,
  );
  console.log(
    `cold run ms median/p95: ${f(report.cold.totalRunMs.median)} / ` +
      `${f(report.cold.totalRunMs.p95)}`,
  );
  console.log(
    `translation ms median/p95: ${f(report.cold.translateMs.median)} / ` +
      `${f(report.cold.translateMs.p95)}`,
  );
  console.log(
    `Wasm compile ms median/p95: ${f(report.cold.compileMs.median)} / ` +
      `${f(report.cold.compileMs.p95)}`,
  );
  console.log(
    `frozen compile ms median/p95: ${f(report.frozenFrontend.compileMs.median)} / ` +
      `${f(report.frozenFrontend.compileMs.p95)}`,
  );
}
